#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

static void bubble_sort(int64_t *arr, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        for (size_t j = 0; j + 1 < len - i; ++j) {
            if (arr[j] > arr[j + 1]) {
                int64_t tmp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tmp;
            }
        }
    }
}

bool isPermutation(int64_t *n, size_t n_len, int64_t *m, size_t m_len) {
    if (n_len != m_len) {
        return false;
    }
    if (n_len == 0) {
        return true;
    }

    int64_t *n_copy = malloc(n_len * sizeof(int64_t));
    int64_t *m_copy = malloc(m_len * sizeof(int64_t));
    if (!n_copy || !m_copy) {
        free(n_copy);
        free(m_copy);
        return false;
    }

    for (size_t i = 0; i < n_len; ++i) {
        n_copy[i] = n[i];
        m_copy[i] = m[i];
    }

    bubble_sort(n_copy, n_len);
    bubble_sort(m_copy, m_len);

    for (size_t i = 0; i < n_len; ++i) {
        if (n_copy[i] != m_copy[i]) {
            free(n_copy);
            free(m_copy);
            return false;
        }
    }

    free(n_copy);
    free(m_copy);
    return true;
}

int main(void) {
    // Test 1: identical arrays
    {
        int64_t a1[] = {1, 2, 3, 4, 5};
        int64_t a2[] = {1, 2, 3, 4, 5};
        bool r = isPermutation(a1, 5, a2, 5);
        printf("%d\n", r);
    }

    // Test 2: permutation
    {
        int64_t a1[] = {5, 3, 1, 4, 2};
        int64_t a2[] = {1, 2, 3, 4, 5};
        bool r = isPermutation(a1, 5, a2, 5);
        printf("%d\n", r);
    }

    // Test 3: different lengths
    {
        int64_t a1[] = {1, 2, 3};
        int64_t a2[] = {1, 2, 3, 4};
        bool r = isPermutation(a1, 3, a2, 4);
        printf("%d\n", r);
    }

    // Test 4: empty arrays
    {
        int64_t a1[] = {};
        int64_t a2[] = {};
        bool r = isPermutation(a1, 0, a2, 0);
        printf("%d\n", r);
    }

    // Test 5: same elements, different multiplicities
    {
        int64_t a1[] = {1, 1, 2};
        int64_t a2[] = {1, 2, 2};
        bool r = isPermutation(a1, 3, a2, 3);
        printf("%d\n", r);
    }

    // Test 6: negative numbers and zero
    {
        int64_t a1[] = {-5, 0, 7, -2};
        int64_t a2[] = {7, -2, -5, 0};
        bool r = isPermutation(a1, 4, a2, 4);
        printf("%d\n", r);
    }

    // Test 7: single element mismatch
    {
        int64_t a1[] = {100, 200, 300};
        int64_t a2[] = {100, 200, 301};
        bool r = isPermutation(a1, 3, a2, 3);
        printf("%d\n", r);
    }

    return 0;
}

