import java.util.Arrays;

public class Solution {
    public static boolean isPermutation(int[] n, int[] m) {
        if (n.length != m.length) {
            return false;
        }
        int[] sortedN = n.clone();
        int[] sortedM = m.clone();
        Arrays.sort(sortedN);
        Arrays.sort(sortedM);
        for (int i = 0; i < sortedN.length; i++) {
            if (sortedN[i] != sortedM[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Test case 1: identical arrays
        int[] a1 = {1, 2, 3, 4, 5};
        int[] b1 = {1, 2, 3, 4, 5};
        System.out.println(isPermutation(a1, b1)); // true

        // Test case 2: permutation
        int[] a2 = {5, 3, 1, 4, 2};
        int[] b2 = {1, 2, 3, 4, 5};
        System.out.println(isPermutation(a2, b2)); // true

        // Test case 3: different lengths
        int[] a3 = {1, 2, 3};
        int[] b3 = {1, 2, 3, 4};
        System.out.println(isPermutation(a3, b3)); // false

        // Test case 4: same length, different elements
        int[] a4 = {1, 2, 3, 4};
        int[] b4 = {1, 2, 3, 5};
        System.out.println(isPermutation(a4, b4)); // false

        // Test case 5: empty arrays
        int[] a5 = {};
        int[] b5 = {};
        System.out.println(isPermutation(a5, b5)); // true

        // Test case 6: arrays with zeros and negatives
        int[] a6 = {0, -1, 7, 0};
        int[] b6 = {7, 0, 0, -1};
        System.out.println(isPermutation(a6, b6)); // true

        // Test case 7: single element mismatch
        int[] a7 = {42};
        int[] b7 = {24};
        System.out.println(isPermutation(a7, b7)); // false
    }
}
